scripts.orchard:
/**
 * A tree that drops an apple now and then.
 *
 * The whole of "apples fall": a deadline on `world.time`, which is the clock
 * every client agrees about, so four browsers grow the same fruit at the same
 * moment without anybody sending anything. A timer per machine would not.
 *
 * It counts what it has dropped rather than what is lying about, and stops at
 * a few: an orchard nobody eats from should not fill the park by teatime.
 */
const EVERY = 9
const MOST = 3

let next = 0
let out = 0

function onSpawn() {
  // Staggered by where the tree stands, so four trees do not fruit in unison.
  next = 2 + Math.abs(self.x + self.z) * 0.11
}

function onTick() {
  if (world.time < next) return
  next = world.time + EVERY
  if (out >= MOST) return
  out += 1
  // Just off the trunk and above head height: an apple has to fall to be worth
  // waiting for, and the world's own gravity is not a thing an entity has.
  const apple = self.spawn('apple', world.random() * 2 - 1, 3.2, world.random() * 2 - 1)
  if (apple) apple.set('from', self.id)
}

scripts.hero:
/**
 * The strength bar, and what being full of it does to a dash.
 *
 * The rules do the parts that are sentences about the game - the dash key
 * dashes, a critter that goes down adds to `strength` - and this does the part
 * that is a clock: a mega dash lasts a moment, and something has to end it.
 *
 * `mega` is a property on the body rather than a field of the level because it
 * is a fact about *this* player. A critter reads it off whoever touched them.
 */
const MEGA_FOR = 0.45

let until = 0

function onTick() {
  const full = world.get('strength') >= 4

  if (self.get('mega') > 0 && until === 0) {
    until = world.time + MEGA_FOR
    self.material = 'rainbow'
  }

  if (until > 0 && world.time >= until) {
    until = 0
    self.set('mega', 0)
    // Spent. The bar goes back to nothing, which is what makes a mega dash a
    // thing you save up for rather than a thing you have.
    world.set('strength', 0)
    self.material = 'own'
  }

  // A hint that it is ready, when it is and nothing is running: the body itself
  // glows faintly rather than the HUD growing another number.
  if (full && until === 0 && self.material === 'own') self.material = 'rainbow'
  if (!full && until === 0 && self.material === 'rainbow') self.material = 'own'
}

scripts.critter:
/**
 * Somebody to knock over: a peep that wanders its own patch.
 *
 * A patch and not the park, because a critter that walked off would be a level
 * that empties itself. Where it started is remembered on the first tick - an
 * entity knows where it *is*, and where it belongs is this script's business.
 */
const PATCH = 5
const PACE = 1.8

let homeX = null
let homeZ = null
let goX = 0
let goZ = 0
let turn = 0

function onTick(dt) {
  if (homeX === null) {
    homeX = self.x
    homeZ = self.z
  }

  if (world.time >= turn) {
    turn = world.time + 2 + world.random() * 3
    const angle = world.random() * Math.PI * 2
    goX = Math.sin(angle)
    goZ = Math.cos(angle)
  }

  // Turned back at the edge of its patch rather than clamped, so it paces about
  // instead of standing against an invisible wall.
  const outX = self.x - homeX
  const outZ = self.z - homeZ
  if (Math.sqrt(outX * outX + outZ * outZ) > PATCH) {
    const back = Math.sqrt(outX * outX + outZ * outZ)
    goX = -outX / back
    goZ = -outZ / back
  }

  self.moveBy(goX * PACE * dt, 0, goZ * PACE * dt)
  self.rotation = (Math.atan2(goX, goZ) * 180) / Math.PI
}
